  "Certificate storage is currently unavailable. This does not mean you have no certificates.": {"en":"Certificate storage is currently unavailable. This does not mean you have no certificates.","pt-BR":"O armazenamento de certificados está indisponível no momento. Isso não significa que você não tenha certificados.","es":"El almacenamiento de certificados no está disponible. Esto no significa que no tengas certificados.","fr":"Le stockage des certificats est indisponible. Cela ne signifie pas que vous n’avez aucun certificat.","de":"Der Zertifikatsspeicher ist derzeit nicht verfügbar. Das bedeutet nicht, dass du keine Zertifikate hast.","it":"L’archivio dei certificati non è disponibile. Questo non significa che tu non abbia certificati."},
  "Certificates could not be loaded.": {"en":"Certificates could not be loaded.","pt-BR":"Não foi possível carregar os certificados.","es":"No se pudieron cargar los certificados.","fr":"Impossible de charger les certificats.","de":"Zertifikate konnten nicht geladen werden.","it":"Impossibile caricare i certificati."},
