  "Continue with context.": {"en":"Continue with context.","pt-BR":"Retome de onde parou.","es":"Retoma donde lo dejaste.","fr":"Reprenez là où vous en étiez.","de":"Setze dort fort, wo du aufgehört hast.","it":"Riprendi da dove eri rimasto."},
  "Country Fit / live research": {"en":"Country Fit / live research","pt-BR":"País ideal / pesquisa atual","es":"País ideal / investigación actual","fr":"Pays adapté / recherche actuelle","de":"Country Fit / aktuelle Recherche","it":"Paese ideale / ricerca attuale"},
  "Decide: comparison and budget estimate, each worth 50% when recorded.": {"en":"Decide: comparison and budget estimate, each worth 50% when recorded.","pt-BR":"Decidir: comparação e estimativa de orçamento, cada uma vale 50% quando registrada.","es":"Decidir: comparación y presupuesto estimado, cada uno vale un 50% al registrarse.","fr":"Décider : comparaison et estimation budgétaire, chacune vaut 50 % une fois enregistrée.","de":"Entscheiden: Vergleich und Budgetschätzung zählen jeweils 50 %, sobald sie erfasst sind.","it":"Decidere: confronto e stima del budget valgono ciascuno il 50% quando registrati."},
  "Develop: recorded lesson checkpoints divided by recorded course lesson totals.": {"en":"Develop: recorded lesson checkpoints divided by recorded course lesson totals.","pt-BR":"Desenvolver: verificações de aulas registradas divididas pelo total de aulas dos cursos registrados.","es":"Desarrollar: controles de lecciones registrados divididos por el total de lecciones de los cursos registrados.","fr":"Développer : contrôles de leçons enregistrés divisés par le nombre total de leçons des cours enregistrés.","de":"Entwickeln: erfasste Lernkontrollen geteilt durch die Gesamtzahl der Lektionen der erfassten Kurse.","it":"Sviluppare: verifiche delle lezioni registrate divise per il totale delle lezioni dei corsi registrati."},
  "Discover: five context groups, each worth 20%.": {"en":"Discover: five context groups, each worth 20%.","pt-BR":"Descobrir: cinco grupos de contexto, cada um vale 20%.","es":"Descubrir: cinco grupos de contexto, cada uno vale un 20%.","fr":"Découvrir : cinq groupes de contexte, chacun vaut 20 %.","de":"Entdecken: fünf Kontextgruppen, jede zählt 20 %.","it":"Scoprire: cinque gruppi di contesto, ciascuno vale il 20%."},
  "Edit goal and destinations ↗": {"en":"Edit goal and destinations ↗","pt-BR":"Editar objetivo e destinos ↗","es":"Editar objetivo y destinos ↗","fr":"Modifier l’objectif et les destinations ↗","de":"Ziel und Reiseziele bearbeiten ↗","it":"Modifica obiettivo e destinazioni ↗"},
  "Explore communities →": {"en":"Explore communities →","pt-BR":"Explorar comunidades →","es":"Explorar comunidades →","fr":"Explorer les communautés →","de":"Communitys entdecken →","it":"Esplora le comunità →"},
  "Find a learning path ↗": {"en":"Find a learning path ↗","pt-BR":"Encontrar um percurso de aprendizagem ↗","es":"Buscar un itinerario de aprendizaje ↗","fr":"Trouver un parcours d’apprentissage ↗","de":"Einen Lernpfad finden ↗","it":"Trova un percorso di apprendimento ↗"},
