  "One workspace. Every tool.": {"en":"One workspace. Every tool.","pt-BR":"Um espaço. Todas as ferramentas.","es":"Un espacio. Todas las herramientas.","fr":"Un espace. Tous les outils.","de":"Ein Arbeitsbereich. Alle Werkzeuge.","it":"Uno spazio. Tutti gli strumenti."},
  "Only fields allowed by your public profile settings are shared.": {"en":"Only fields allowed by your public profile settings are shared.","pt-BR":"Somente os campos permitidos nas configurações do seu perfil público são compartilhados.","es":"Solo se comparten los campos permitidos en la configuración de tu perfil público.","fr":"Seuls les champs autorisés dans les paramètres de votre profil public sont partagés.","de":"Nur die in deinen öffentlichen Profileinstellungen freigegebenen Felder werden geteilt.","it":"Vengono condivisi solo i campi consentiti dalle impostazioni del tuo profilo pubblico."},
  "Open certificate center ↗": {"en":"Open certificate center ↗","pt-BR":"Abrir central de certificados ↗","es":"Abrir centro de certificados ↗","fr":"Ouvrir le centre des certificats ↗","de":"Zertifikatscenter öffnen ↗","it":"Apri il centro certificati ↗"},
