  "Open Global Key ↗": {"en":"Open Global Key ↗","pt-BR":"Abrir Global Key ↗","es":"Abrir Global Key ↗","fr":"Ouvrir Global Key ↗","de":"Global Key öffnen ↗","it":"Apri Global Key ↗"},
