  "See criteria ↓": {"en":"See criteria ↓","pt-BR":"Ver critérios ↓","es":"Ver criterios ↓","fr":"Voir les critères ↓","de":"Kriterien ansehen ↓","it":"Vedi i criteri ↓"},
