export type MessageKey = keyof typeof messages;
// Widen lookup values while keeping MessageKey and six-locale authoring checks exact.
// Large catalogs must not expand every translated string into a compiler union.
const catalog: Readonly<Record<string, Readonly<Record<Locale, string>>>> = messages;
/** Normalize authored copy, never persisted values or user contributions. */
function normalizeMessage(text: string): string {
  return text.normalize('NFC').replace(/\s+/g, ' ').trim().toLowerCase();
}
const normalizedMessages = new Map(Object.entries(catalog).map(([key, value]) => [normalizeMessage(key), value]));
// Legacy screens sometimes use a translated source string. Only unambiguous aliases
// are accepted; canonical keys always win over aliases from another language.
const sourceAliases = new Map<string, Readonly<Record<Locale, string>> | null>();
for (const entry of Object.values(catalog)) {
  for (const value of Object.values(entry)) {
    const alias = normalizeMessage(value);
    const existing = sourceAliases.get(alias);
    if (existing === undefined) sourceAliases.set(alias, entry);
    else if (existing !== entry) sourceAliases.set(alias, null);
  }
}
function findMessage(key: string): Readonly<Record<Locale, string>> | undefined {
  if (Object.prototype.hasOwnProperty.call(catalog, key)) return catalog[key];
  const normalized = normalizeMessage(key);
  return normalizedMessages.get(normalized) ?? sourceAliases.get(normalized) ?? undefined;
}
function messageTemplate(locale: Locale, key: string): string {
  const direct = findMessage(key);
  if (direct) return direct[locale];
  // Keep decorative arrows, section numbers and punctuation outside the message.
  // Matching is anchored and requires the whole remaining phrase to be registered.
  const decorated = key.match(/^(\d{1,2}\s*[—–/]\s*|[\s\p{S}→←↗↓↑•✓●·—–/]*)(.*?)([\s→←↗↓↑·:./!?…]*)$/u);
  if (decorated && decorated[2]) {
    const core = findMessage(decorated[2]);
    if (core) return decorated[1] + core[locale] + decorated[3];
  }
  return key;
}
export function translate(locale: Locale, key: string, values: Record<string, string | number> = {}): string {
  const template = messageTemplate(locale, key);
  return template.replace(/\{(\w+)\}/g, (match, name: string) => Object.prototype.hasOwnProperty.call(values, name) ? String(values[name]) : match);
}
